public long readLong(final int offset){
    // Validate offset range to avoid ArrayIndexOutOfBoundsException
    if (offset < 0 || offset + 8 > this.data.length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset);
    }
    long value = 0L;
    // Read 8 bytes in big-endian order and accumulate into the long result
    for (int i = 0; i < 8; i++) {
        value = (value << 8) | (this.data[offset + i] & 0xFFL);
    }
    return value;
}

