 * @param dir the directory to delete on exit
 * @throws IOException if an I/O error occurs
 */
private static void deleteDirectoryOnExit(File dir) throws IOException {
    File[] files = dir.listFiles();
    if (files == null) {
        // Treat null as an I/O error; listFiles() returns null if dir is not a directory or an I/O error occurs.
