    } catch (Exception e) {
        throw new IllegalStateException("Failed to create circulator", e);
    }
    Node current = circ.node();
    if (PredicateUtils.testOrIdentity(predicate, current) || current.equals(stop)) {
        return circ;
    }
    while (true) {
        circ.move(); // advance to the next node along the outer face
        current = circ.node();
        if (PredicateUtils.testOrIdentity(predicate, current) || current.equals(stop)) {
            return circ;
        }
        if (current.equals(start)) { // prevent infinite loop
            break;
        }
    }
    return circ; // returned when loop ends or stop reached
}

