protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()){
        return null;
    }
    try {
        // Build adjacency list
        Map<V, List<E>> adjacency = new HashMap<>();
        for (E e : tour){
            V v1 = graph.getEdgeSource(e);
            V v2 = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(v1, k -> new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(v2, k -> new ArrayList<>()).add(e);
        }
        // Pick an arbitrary start vertex
        V start = adjacency.keySet().iterator().next();
        LinkedList<V> vertexList = new LinkedList<>();
        LinkedList<E> edgeList = new LinkedList<>();
        Set<E> usedEdges = new HashSet<>();
        vertexList.add(start);
        V current = start;
        while (edgeList.size() < tour.size()){
            List<E> adjEdges = adjacency.get(current);
            if (adjEdges == null){
                return null; // invalid tour
            }
            E nextEdge = null;
            for (E e : adjEdges){
                if (!usedEdges.contains(e)){
                    nextEdge = e;
                    break;
                }
            }
            if (nextEdge == null){
                return null; // cannot continue
            }
            usedEdges.add(nextEdge);
            edgeList.add(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                            ? graph.getEdgeTarget(nextEdge)
                            : graph.getEdgeSource(nextEdge);
            vertexList.add(nextVertex);
            current = nextVertex;
        }
        // Compute total weight
        double weight = 0.0;
        for (E e : edgeList){
            weight += graph.getEdgeWeight(e);
        }
        return new org.jgrapht.GraphPathImpl<>(graph, start, current, weight, vertexList, edgeList);
    } catch (Exception e){
        return null;
    }
}

