private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate parameters
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> dest;
    if (!bucketsByLabel.isEmpty()) {
        dest = bucketsByLabel.get(0);
    } else {
        dest = null;
    }
    if (dest == null) {
        dest = new HashSet<>();
        if (bucketsByLabel.isEmpty()) {
            bucketsByLabel.add(dest);
        } else {
            bucketsByLabel.set(0, dest);
        }
    }

    // Retrieve the source bucket
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return; // invalid minLabel, nothing to do
    }
    Set<Integer> src = bucketsByLabel.get(minLabel);
    if (src == null || src.isEmpty()) {
        return; // nothing to move
    }

    // Move vertices from src to dest
    // Use a copy to avoid ConcurrentModificationException
    Set<Integer> toMove = new HashSet<>(src);
    for (Integer v : toMove) {
        dest.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }

    // Clear the source bucket
    src.clear();
}

