private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    long sum = 0;
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds element at index " + i + " is null");
        }
        sum += val;
        suffix.add(0, (int)sum);
    }
    long totalSum = sum;
    return new Pair<>(suffix, totalSum);
}

