                    try {
                        start = range.getStartMillis();
                    } catch (Exception ignored) {}
                    try {
                        end = range.getEndMillis();
                    } catch (Exception ignored) {}
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
