public static int nextPrime(int desiredCapacity){
    // Handle invalid or small desired capacities
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start from the desired capacity, ensuring it is odd (except for 2)
    int n = desiredCapacity;
    if (n % 2 == 0) {
        n++; // make it odd
    }
    // Search upwards for the next prime number
    while (true) {
        boolean isPrime = true;
        int sqrt = (int)Math.sqrt(n);
        // Only trial division by odd numbers up to sqrt
        for (int divisor = 3; divisor <= sqrt; divisor += 2) {
            if (n % divisor == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return n;
        }
        // Increment by 2 to keep n odd
        n += 2;
        // If overflow occurs, fall back to Integer.MAX_VALUE
        if (n <= 0) {
            return Integer.MAX_VALUE;
        }
    }
}

