public String readString() throws IOException {
    // read a big-endian 4-byte length prefix
    int b1 = in.read();
    if (b1 == -1) throw new EOFException("Unexpected end of stream");
    int b2 = in.read();
    if (b2 == -1) throw new EOFException("Unexpected end of stream");
    int b3 = in.read();
    if (b3 == -1) throw new EOFException("Unexpected end of stream");
    int b4 = in.read();
    if (b4 == -1) throw new EOFException("Unexpected end of stream");
    int len = ((b1 & 0xFF) << 24) | ((b2 & 0xFF) << 16) | ((b3 & 0xFF) << 8) | (b4 & 0xFF);
    if (len < 0) throw new IOException("Negative string length");
    if (len == 0) return "";
    byte[] bytes = new byte[len];
    int read = 0;
    while (read < len) {
        int r = in.read(bytes, read, len - read);
        if (r == -1) throw new EOFException("Unexpected end of stream while reading string");
        read += r;
    }
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

